WITH exploded AS (SELECT id, service, host, log_ts, level, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, attr_value) SELECT *, FIRST_VALUE(k) IGNORE NULLS OVER (PARTITION BY k ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_k, LAST_VALUE(k) IGNORE NULLS OVER (PARTITION BY host, service ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_k, FIRST_VALUE(k) IGNORE NULLS OVER (PARTITION BY service, k ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_k_2, ROW_NUMBER() OVER (PARTITION BY k ORDER BY log_ts, id, k) AS event_seq, ROW_NUMBER() OVER (PARTITION BY service ORDER BY log_ts DESC, id, k) AS event_seq_2 FROM exploded;
